const ctx = $('Load Booking Context').first().json;
const events = $input.all().map(function (i) { return i.json; }).filter(function (e) { return e && e.start; });

const marketTz = ctx.market_tz || 'Asia/Dubai';
const leadTz = ctx.lead_tz || marketTz;
const wh = ctx.working_hours || {};
const minNotice = Number(ctx.min_notice_hours || 3);
const windowDays = Number(ctx.booking_window_days || 7);
const durationMin = 60;

const nowUtc = DateTime.utc();
const startBound = nowUtc.plus({ hours: minNotice });
const endBound = nowUtc.plus({ days: windowDays });

const busy = [];
for (const e of events) {
  if (e.status === 'cancelled') continue;
  const s = e.start ? (e.start.dateTime || e.start.date) : null;
  const en = e.end ? (e.end.dateTime || e.end.date) : null;
  if (!s || !en) continue;
  busy.push({ s: DateTime.fromISO(s).toUTC(), e: DateTime.fromISO(en).toUTC() });
}

const dayKeys = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const candidates = [];
let cursor = startBound.setZone(marketTz).startOf('day');
const lastDay = endBound.setZone(marketTz).endOf('day');

while (cursor <= lastDay) {
  const key = dayKeys[cursor.weekday % 7];
  const hours = wh[key];
  if (Array.isArray(hours) && hours.length === 2 && hours[0] && hours[1]) {
    const openParts = String(hours[0]).split(':');
    const closeParts = String(hours[1]).split(':');
    let slot = cursor.set({ hour: Number(openParts[0]), minute: Number(openParts[1] || 0), second: 0, millisecond: 0 });
    const close = cursor.set({ hour: Number(closeParts[0]), minute: Number(closeParts[1] || 0), second: 0, millisecond: 0 });
    while (slot.plus({ minutes: durationMin }) <= close) {
      const sUtc = slot.toUTC();
      const eUtc = sUtc.plus({ minutes: durationMin });
      if (sUtc >= startBound && sUtc <= endBound) {
        let clash = false;
        for (const b of busy) { if (sUtc < b.e && b.s < eUtc) { clash = true; break; } }
        if (!clash) candidates.push(sUtc);
      }
      slot = slot.plus({ minutes: durationMin });
    }
  }
  cursor = cursor.plus({ days: 1 });
}

const byDay = {};
for (const c of candidates) {
  const k = c.setZone(marketTz).toFormat('yyyy-LL-dd');
  if (!byDay[k]) byDay[k] = [];
  byDay[k].push(c);
}
const days = Object.keys(byDay).sort();
const chosen = [];
for (const d of days) {
  if (chosen.length >= 3) break;
  chosen.push(byDay[d][0]);
}
if (chosen.length < 3) {
  for (const d of days) {
    for (const c of byDay[d]) {
      if (chosen.length >= 3) break;
      let dup = false;
      for (const x of chosen) { if (x.toMillis() === c.toMillis()) { dup = true; break; } }
      if (!dup) chosen.push(c);
    }
    if (chosen.length >= 3) break;
  }
}
chosen.sort(function (a, b) { return a.toMillis() - b.toMillis(); });

const slots = chosen.map(function (c) {
  return {
    starts_at_utc: c.toISO(),
    ends_at_utc: c.plus({ minutes: durationMin }).toISO(),
    label_local: c.setZone(leadTz).toFormat('ccc d LLL, h:mm a')
  };
});

return [{ json: {
  ok: slots.length > 0,
  slots: slots,
  slots_json: JSON.stringify(slots),
  conversation_id: ctx.conversation_id,
  lead_id: ctx.lead_id,
  agent_id: ctx.agent_id
} }];
